<?php
declare(strict_types=1); namespace Theobroma\OneC\Import;
final class OrderStatusImportParser {private const MAP=['processing'=>'processing','оплачен'=>'processing','в обработке'=>'processing','completed'=>'completed','завершен'=>'completed','выполнен'=>'completed','cancelled'=>'cancelled','отменен'=>'cancelled','refunded'=>'refunded','возврат'=>'refunded'];/** @return list<OrderStatusUpdate> */public function parse(string$xml,int$limit=10485760):array{$root=SafeXml::load($xml,$limit);$out=[];foreach($root->xpath('//*[local-name()="Документ"]')?:[] as$n){if(!preg_match('/^WC-ORDER-(\d+)$/',SafeXml::value($n,'Ид'),$m))continue;$status='';foreach($n->xpath('.//*[local-name()="ЗначениеРеквизита"]')?:[] as$r)if(mb_strtolower(SafeXml::value($r,'Наименование'))==='статус заказа'){$status=mb_strtolower(SafeXml::value($r,'Значение'));break;}if(isset(self::MAP[$status]))$out[]=new OrderStatusUpdate((int)$m[1],self::MAP[$status]);}return$out;}}
